head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
scwin.procsNo;
scwin.gRegEmpNo;
scwin.vScrenID = "ULDSTF07061.xml";
scwin.vListProcsStatCd = "";
scwin.vListBzDtlTpCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/lstinvstg/ListFee.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getInfo" + "&BZ_PROCS_NO=" + scwin.procsNo + "&LIST_BZ_DTL_TP_CD=" + scwin.vListBzDtlTpCd;
    trs_Read.KeyValue = "JSP(O:pOutput=dts_ContentsInfo)";
    trs_Read.Post();
};
scwin.fn_save = function(listProcsStatCd) {
    scwin.fn_setHeader();
    dts_ProcData.insertRow();
    dts_ProcData.setCellData(1, "BZ_PROCS_NO", scwin.procsNo);
    dts_ProcData.setCellData(1, "LIST_BZ_DTL_TP_CD", scwin.vListBzDtlTpCd);
    dts_ProcData.setCellData(1, "LIST_PROCS_STAT_CD", listProcsStatCd);
    trs_Save.Action = "/lstinvstg/ListFee.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=setListFeeStatus";
    trs_Save.KeyValue = "JSP(I:pInput=dts_ProcData)";
    trs_Save.Post();
};
scwin.fn_setHeader = function() {
    dts_ProcData.removeAll();
    //dts_ProcData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_print = function() {
    var arrAmt = ["", "", "", "", "", "", "", "", ""];
    var payAmt = dts_ContentsInfo.getCellData(1, "PAY_AMT");
    var len = payAmt.length;
    for (var i = 0; i < payAmt.length; i++) {
        arrAmt[i] = payAmt.substring((len - (i + 1)), len - i);
    }
    var userParam = [{
        uid: "comNm",
        unm: dts_ContentsInfo.getCellData(1, "ISUR_NM")
    }, {
        uid: "lstPayAmt1",
        unm: arrAmt[0]
    }, {
        uid: "lstPayAmt2",
        unm: arrAmt[1]
    }, {
        uid: "lstPayAmt3",
        unm: arrAmt[2]
    }, {
        uid: "lstPayAmt4",
        unm: arrAmt[3]
    }, {
        uid: "lstPayAmt5",
        unm: arrAmt[4]
    }, {
        uid: "lstPayAmt6",
        unm: arrAmt[5]
    }, {
        uid: "lstPayAmt7",
        unm: arrAmt[6]
    }, {
        uid: "lstPayAmt8",
        unm: arrAmt[7]
    }, {
        uid: "lstPayAmt9",
        unm: arrAmt[8]
    }, {
        uid: "feeNm",
        unm: dts_ContentsInfo.getCellData(1, "LIST_FEE_ANULFEE_TP_NM")
    }, {
        uid: "printDate2",
        unm: $c.ut.cGetToday("yyyy-mm-dd")
    }];
    var pdf_rptname = "RLDSTF00034";
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};
scwin.fn_print_old = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var arrAmt = ["", "", "", "", "", "", "", "", ""];
    var payAmt = dts_ContentsInfo.getCellData(1, "PAY_AMT");
    var len = payAmt.length;
    for (var i = 0; i < payAmt.length; i++) {
        arrAmt[i] = payAmt.substring((len - (i + 1)), len - i);
    }
    dts_Print.insertRow();
    dts_Print.setCellData(1, "comNm", dts_ContentsInfo.getCellData(1, "ISUR_NM"));
    dts_Print.setCellData(1, "lstPayAmt1", arrAmt[0]);
    dts_Print.setCellData(1, "lstPayAmt2", arrAmt[1]);
    dts_Print.setCellData(1, "lstPayAmt3", arrAmt[2]);
    dts_Print.setCellData(1, "lstPayAmt4", arrAmt[3]);
    dts_Print.setCellData(1, "lstPayAmt5", arrAmt[4]);
    dts_Print.setCellData(1, "lstPayAmt6", arrAmt[5]);
    dts_Print.setCellData(1, "lstPayAmt7", arrAmt[6]);
    dts_Print.setCellData(1, "lstPayAmt8", arrAmt[7]);
    dts_Print.setCellData(1, "lstPayAmt9", arrAmt[8]);
    dts_Print.setCellData(1, "feeNm", dts_ContentsInfo.getCellData(1, "LIST_FEE_ANULFEE_TP_NM"));
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    var rex_rptname = "RLDFIL00034";
    $c.rpt.fn_open_report(testDateSet, rex_rptname, dts_ContentsInfo);
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "승인"));
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "승인"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.dts_ContentsInfo_OnLoadError = function() {
    $c.win.alert('dts_ContentsInfo.OnLoadError()');
};
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    if ("32" != scwin.vListProcsStatCd) {
        btn_save.src = "../img/btn_approval_d.gif";
        btn_save.setDisabled(true);
        btn_delete.src = "../img/btn_reject_d.gif";
        btn_delete.setDisabled(true);
    }
};
scwin.dts_Report_OnLoadError = function() {
    $c.stf.alert_error(dts_Report);
};
scwin.btn_save_onclick = function() {
    var rtn = confirm('승인 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        scwin.fn_save("33");
    }
};
scwin.btn_delete_onclick = function() {
    var rtn = confirm('반려 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        scwin.fn_save("37");
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.btn_Print_onclick = function() {
    scwin.fn_print();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    var parentWin = $c.frame.path("../");
    //var parentYn = parentWin.procsNo;

    getProcsNo = parentWin.fn_getProcsNo;
    scwin.procsNo = getProcsNo();
    scwin.vListBzDtlTpCd = parentWin.clickListBzDtlTpCd;
    scwin.vListProcsStatCd = parentWin.clickListProcsStatCd;
    scwin.fn_read();
};
